import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Developer attempted input validation but missed edge cases
    private static final Pattern SAFE_PATTERN = Pattern.compile("^[a-zA-Z0-9_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortColumn = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate reportType
        if (reportType == null || !SAFE_PATTERN.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate sort column
        if (sortColumn == null || !SAFE_PATTERN.matcher(sortColumn).matches()) {
            sortColumn = "created_at";
        }

        // Date validation - basic format check
        if (startDate == null || !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date");
            return;
        }
        if (endDate == null || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date");
            return;
        }

        // customFilter is used for advanced filtering - passed directly
        // Developer note: "filter is validated by the frontend React component"

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = "SELECT * FROM reports WHERE report_type = '" + reportType + "'"
                + " AND created_at BETWEEN '" + startDate + "' AND '" + endDate + "'"
                + " AND status = 'published'";

            if (customFilter != null && !customFilter.isEmpty()) {
                // This is the vulnerable path - customFilter is not validated
                query += " AND " + customFilter;
            }

            query += " ORDER BY " + sortColumn + " DESC LIMIT 100";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {\"id\": " + rs.getInt("id") + ",");
                out.print(" \"title\": \"" + rs.getString("title") + "\",");
                out.print(" \"created_at\": \"" + rs.getString("created_at") + "\",");
                out.print(" \"author\": \"" + rs.getString("author") + "\"}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            // Log full error for debugging
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report - uses PreparedStatement (safe)
        String title = req.getParameter("title");
        String body = req.getParameter("body");
        String author = req.getParameter("author");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO reports (title, body, author, status, report_type) VALUES (?, ?, ?, 'draft', 'standard')"
            );
            ps.setString(1, title);
            ps.setString(2, body);
            ps.setString(3, author);
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
